		return
	var log_file := FileAccess.open("res://.git/logs/HEAD", FileAccess.READ)
	if not check("git_log", log_file != null, "La cronologia Git deve contenere il commit di configurazione registrato"):
		return
	var content: String = log_file.get_as_text()
	var lines: PackedStringArray = content.split("\n", false)
	var commit_count: int = 0
	for line in lines:
		if line.find("commit") != -1:
			commit_count += 1
	check("commit_present", commit_count >= 1, "Deve essere presente almeno un commit registrato nell'archivio (trovati: %d)" % commit_count)

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var head_file := FileAccess.open("res://.git/HEAD", FileAccess.READ)
	if not check("git_head", head_file != null, "L'archivio Git deve essere presente"):
		return

	var log_file := FileAccess.open("res://.git/logs/HEAD", FileAccess.READ)
	if not check("git_log", log_file != null, "Il file di registro .git/logs/HEAD deve esistere"):
		return

	var content: String = log_file.get_as_text()
	var lines: PackedStringArray = content.split("\n", false)
	var commit_messages: Array[String] = []

	for line in lines:
		var commit_idx: int = line.find("commit")
		if commit_idx != -1:
			var msg_part: String = line.substr(commit_idx)
			var colon_idx: int = msg_part.find(":")
			if colon_idx != -1:
				msg_part = msg_part.substr(colon_idx + 1)
			var cleaned: String = msg_part.strip_edges()
			if not cleaned.is_empty():
				commit_messages.append(cleaned)

	var count: int = commit_messages.size()
	if not check("commit_count", count >= 5, "La storia di Git deve contenere almeno 5 commit (trovati: %d)" % count):
		return

	var all_long_enough: bool = true
	var unique_messages: Dictionary = {}
	for msg in commit_messages:
		unique_messages[msg] = true
		if msg.length() < 10:
			all_long_enough = false

	check("commit_len", all_long_enough, "Tutti i messaggi dei commit devono essere descrittivi (almeno 10 caratteri)")
	check("commit_unique", unique_messages.size() >= 5, "I messaggi dei commit devono essere tutti distinti tra loro")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	QuizData.score = 3
	QuizData.high_score = 3
	QuizData.current_topic_title = ""
	var results_scene := await instantiate_scene("res://results.tscn")
	if not check("results_loaded", results_scene != null, "La scena res://results.tscn deve aprirsi senza errori"):
		return

	var score_label := find_by_name(results_scene, "ScoreLabel") as Label
	if not check("score_label", score_label != null, "Nella scena results.tscn deve esserci la Label ScoreLabel"):
		return

	check("record_text", score_label.text.find("Nuovo Record!") != -1, "Quando il punteggio eguaglia il record (e > 0), ScoreLabel deve contenere 'Nuovo Record!' (testo: '%s')" % score_label.text)

	results_scene.queue_free()
	await wait_frames(2)
	QuizData.score = 0
	QuizData.high_score = 0
	results_scene = await instantiate_scene("res://results.tscn")
	if results_scene != null:
		score_label = find_by_name(results_scene, "ScoreLabel") as Label
		if score_label != null:
			check("no_record_at_zero", score_label.text.find("Nuovo Record!") == -1, "Con punteggio pari a 0 non deve comparire 'Nuovo Record!'")

	var log_file := FileAccess.open("res://.git/logs/HEAD", FileAccess.READ)
	if not check("git_log", log_file != null, "Il file .git/logs/HEAD deve esistere"):
		return

	var content: String = log_file.get_as_text()
	var lines: PackedStringArray = content.split("\n", false)
	var commit_messages: Array[String] = []

	for line in lines:
		var commit_idx: int = line.find("commit")
		if commit_idx != -1:
			var msg_part: String = line.substr(commit_idx)
			var colon_idx: int = msg_part.find(":")
			if colon_idx != -1:
				msg_part = msg_part.substr(colon_idx + 1)
			var cleaned: String = msg_part.strip_edges()
			if not cleaned.is_empty():
				commit_messages.append(cleaned)

	var count: int = commit_messages.size()
	if not check("commit_count", count >= 6, "La storia di Git deve contenere almeno 6 commit dopo l'aggiunta della miglioria (trovati: %d)" % count):
		return

	var all_long_enough: bool = true
	var unique_messages: Dictionary = {}
	for msg in commit_messages:
		unique_messages[msg] = true
		if msg.length() < 10:
			all_long_enough = false

	check("commit_len", all_long_enough, "Tutti i messaggi dei commit devono essere descrittivi (almeno 10 caratteri)")
	check("commit_unique", unique_messages.size() >= 6, "I messaggi dei commit devono essere tutti distinti tra loro")

